Test("Compose runs the inner function first", () =>
{
    var shout = Compose<string, string, string>(s => s + "!", s => s.ToUpperInvariant());
    Eq(shout("hi"), "HI!");
});

Test("Compose can change the type on the way through", () =>
{
    var lengthPlusOne = Compose<string, int, int>(n => n + 1, s => s.Length);
    Eq(lengthPlusOne("abc"), 4);
});

Test("Pipe applies the steps left to right", () =>
{
    var f = Pipe<int>(x => x + 1, x => x * 10);
    Eq(f(2), 30);
});

Test("Pipe of nothing is the identity", () => Eq(Pipe<int>()(7), 7));

Test("Pipe of one step is that step", () => Eq(Pipe<int>(x => x - 1)(7), 6));

Test("Tap returns the original answer", () => Eq(Tap<int, int>(x => x * 2, _ => { })(5), 10));

Test("Tap sees the input", () =>
{
    var seen = new List<int>();
    var doubled = Tap<int, int>(x => x * 2, seen.Add);
    doubled(3);
    doubled(4);
    Eq(seen, new List<int> { 3, 4 });
});

Test("Tap observes even when the pipeline is composed", () =>
{
    var seen = new List<int>();
    var f = Pipe<int>(Tap<int, int>(x => x + 1, seen.Add), x => x * 2);
    Eq(f(1), 4);
    Eq(seen, new List<int> { 1 });
});

return Report();

// ─── tests ───────────────────────────────────────────────────────────────

Test("the wrapped function still returns the right answer", () =>
{
    var square = Memoize<int, int>(x => x * x);
    Eq(square(4), 16);
});

Test("the same argument is computed once", () =>
{
    var calls = 0;
    var square = Memoize<int, int>(x => { calls++; return x * x; });
    square(4);
    square(4);
    square(4);
    Eq(calls, 1);
});

Test("different arguments are computed separately", () =>
{
    var calls = 0;
    var square = Memoize<int, int>(x => { calls++; return x * x; });
    Eq((square(2), square(3), square(2)), (4, 9, 4));
    Eq(calls, 2);
});

Test("a null result is still remembered", () =>
{
    var calls = 0;
    var lookup = Memoize<string, string?>(_ => { calls++; return null; });
    lookup("missing");
    lookup("missing");
    Eq(calls, 1, "null is an answer, not a cache miss");
});

Test("two wrappers do not share a cache", () =>
{
    var calls = 0;
    Func<int, int> f = x => { calls++; return x; };
    var a = Memoize(f);
    var b = Memoize(f);
    a(1);
    b(1);
    Eq(calls, 2);
});

Test("MemoizeTwo keys on both arguments", () =>
{
    var calls = 0;
    var add = MemoizeTwo<int, int, int>((x, y) => { calls++; return x + y; });
    Eq((add(1, 2), add(1, 2), add(2, 1)), (3, 3, 3));
    Eq(calls, 2, "(1,2) and (2,1) are different keys");
});

Test("MemoizeTwo works with mixed types", () =>
{
    var repeat = MemoizeTwo<string, int, string>((s, n) => string.Concat(Enumerable.Repeat(s, n)));
    Eq(repeat("ab", 2), "abab");
});

return Report();

// ─── tests ───────────────────────────────────────────────────────────────

Test("publishing with no subscribers does nothing", () =>
{
    var publisher = new Publisher();
    publisher.Publish("hello");
    Eq(publisher.SubscriberCount, 0);
});

Test("a subscriber receives the message", () =>
{
    var seen = new List<string>();
    var publisher = new Publisher();
    publisher.Published += (_, message) => seen.Add(message);
    publisher.Publish("hello");
    Eq(seen, new List<string> { "hello" });
});

Test("every subscriber receives it, in order", () =>
{
    var seen = new List<string>();
    var publisher = new Publisher();
    publisher.Published += (_, m) => seen.Add("a:" + m);
    publisher.Published += (_, m) => seen.Add("b:" + m);
    publisher.Publish("x");
    Eq(seen, new List<string> { "a:x", "b:x" });
});

Test("SubscriberCount tracks attachments", () =>
{
    var publisher = new Publisher();
    EventHandler<string> handler = (_, _) => { };
    Eq(publisher.SubscriberCount, 0);
    publisher.Published += handler;
    Eq(publisher.SubscriberCount, 1);
    publisher.Published += handler;
    Eq(publisher.SubscriberCount, 2, "the same handler attached twice fires twice");
});

Test("detaching removes one attachment", () =>
{
    var calls = 0;
    var publisher = new Publisher();
    EventHandler<string> handler = (_, _) => calls++;
    publisher.Published += handler;
    publisher.Published -= handler;
    publisher.Publish("x");
    Eq((publisher.SubscriberCount, calls), (0, 0));
});

Test("Reset detaches everyone", () =>
{
    var calls = 0;
    var publisher = new Publisher();
    publisher.Published += (_, _) => calls++;
    publisher.Published += (_, _) => calls++;
    publisher.Reset();
    publisher.Publish("x");
    Eq((publisher.SubscriberCount, calls), (0, 0));
});

Test("the sender is the publisher", () =>
{
    object? sender = null;
    var publisher = new Publisher();
    publisher.Published += (s, _) => sender = s;
    publisher.Publish("x");
    Ok(ReferenceEquals(sender, publisher));
});

return Report();

